def prepare_sql_for_execution(sql: str, executor: Any = None) -> str:
    """Prepare SQL for the driver, using the executor's dialect rules if known.

    Statement terminators are a client-side separator: the multi-statement
    splitter already removes them, and single statements are normalised here so
    that drivers which reject a trailing ';' (oracledb raises ORA-00922) get
    executable SQL too.

    Args:
        sql: Raw SQL from the editor/CLI.
        executor: Optional query executor (usually the adapter). When it
            exposes `prepare_query`, the dialect decides how the SQL is prepared.

    Returns:
        SQL text ready to hand to the database driver.
    """
    if not sql or not sql.strip():
        return sql

    prepare = getattr(executor, "prepare_query", None)
    if callable(prepare):
        try:
            prepared = prepare(sql)
        except Exception:
            return sql
        if isinstance(prepared, str):
            return prepared

    from sqlit.domains.connections.providers.adapters.base import (
        strip_trailing_statement_terminator,
    )

    return strip_trailing_statement_terminator(sql)


