@lru_cache(maxsize=256)
def _get_assigned_attributes(subject: type) -> frozenset[str]:
    """
    Return the names of any attributes assigned in functions defined in ``subject`` or
    any of its base classes.

    Attributes assigned to ``self`` (usually in ``__init__())`` are only present on
    instances, so they cannot be found with :func:`getattr` when the object being
    checked is a class.

    """
    assigned: set[str] = set()
    seen_codes: set[types.CodeType] = set()
    codes: list[types.CodeType] = []
    for klass in subject.__mro__:
        for member in klass.__dict__.values():
            code = getattr(getattr(member, "__func__", member), "__code__", None)
            if isinstance(code, types.CodeType):
                codes.append(code)

    while codes:
        code = codes.pop()
        if code in seen_codes:
            continue

        seen_codes.add(code)
        for instruction in dis.get_instructions(code):
            if instruction.opname == "STORE_ATTR" and isinstance(instruction.argval, str):
                assigned.add(instruction.argval)

        codes.extend(
            const for const in code.co_consts if isinstance(const, types.CodeType)
        )

    return frozenset(assigned)


def _class_has_attribute(subject: type, attrname: str) -> bool:
    """
    Check if instances of ``subject`` are expected to have the given attribute.

    This is used when a class is checked against a protocol, in which case non-method
    members of the protocol generally only exist on instances of the class, and are thus
    invisible to :func:`getattr`.

    """
    # Annotations (either own, inherited from a superclass, or inherited from the
    # protocol itself) declare the attribute as an instance attribute
    for klass in subject.__mro__:
        annotations = klass.__dict__.get("__annotations__")
        if isinstance(annotations, Mapping) and attrname in annotations:
            return True

    # Attributes assigned in methods (typically ``self.attr = ...`` in ``__init__()``)
    # only exist on instances
    if attrname in _get_assigned_attributes(subject):
        return True

    # Dynamically generated attributes cannot be detected in advance
    for klass in subject.__mro__:
        if "__getattr__" in klass.__dict__ or "__getattribute__" in klass.__dict__:
            return True

    return False


def _is_instance_attribute_accessor(value: Any) -> bool:
    """
    Check if ``value`` is an attribute accessor whose actual value only exists on
    instances (e.g. ``property`` or a slot member descriptor).

    """
    if isinstance(
        value,
        (types.FunctionType, types.MethodType, classmethod, staticmethod, type, Mock),
    ):
        return False

    return hasattr(type(value), "__get__")


