from typeguard import check_type, TypeCheckError

class Proto(Protocol):
    foo: str

def expect_ok(fn):
    try:
        fn()
        print("OK  ", fn.__name__)
    except Exception as exc:
        print("FAIL", fn.__name__, type(exc).__name__, exc)

def expect_fail(fn):
    try:
        fn()
        print("FAIL(no error)", fn.__name__)
    except TypeCheckError as exc:
        print("OK  (raised)", fn.__name__, "|", str(exc).split("is not compatible")[-1])
    except Exception as exc:
        print("FAIL(other)", fn.__name__, type(exc).__name__, exc)

def explicit_subclass_init():
    class Class(Proto):
        def __init__(self):
            self.foo = "bar"
    check_type(Class, type[Proto])

def structural_init():
    class Class:
        def __init__(self):
            self.foo = "bar"
    check_type(Class, type[Proto])

def annotated_only():
    class Class:
        foo: str
    check_type(Class, type[Proto])

def class_attribute():
    class Class:
        foo = "bar"
    check_type(Class, type[Proto])

def wrong_type_class_attribute():
    class Class:
        foo = 42
    check_type(Class, type[Proto])

def missing_entirely():
    class Class:
        pass
    check_type(Class, type[Proto])

def inherited_missing():
    class Base:
        pass
    class Class(Base):
        pass
    check_type(Class, type[Proto])

def inherited_attr_via_base():
    class Base:
        def __init__(self):
            self.foo = "x"
    class Class(Base):
        pass
    check_type(Class, type[Proto])

def property_on_class():
    class Class:
        @property
        def foo(self) -> str: return "x"
    check_type(Class, type[Proto])

def slots():
    class Class:
        __slots__ = ("foo",)
        def __init__(self):
            self.foo = "bar"
    check_type(Class, type[Proto])

def getattr_dynamic():
    class Class:
        def __getattr__(self, name): return "x"
    check_type(Class, type[Proto])

def instance_still_checked():
    class Class:
        def __init__(self):
            self.foo = 42
    check_type(Class(), Proto)

def instance_missing_still_fails():
    class Class:
        pass
    check_type(Class(), Proto)

def instance_ok():
    class Class:
        def __init__(self):
            self.foo = "bar"
    check_type(Class(), Proto)

def nested_func_assignment():
    class Class:
        def __init__(self):
            def helper(obj):
                obj.foo = "x"
            helper(self)
    check_type(Class, type[Proto])

